import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Contact } from '../models/contact.model';

@Injectable({
    providedIn: 'root'
})
export class ContactService {
    private readonly STORAGE_KEY = 'locker_contacts';

    private contactsSubject = new BehaviorSubject<Contact[]>([]);
    public contacts$: Observable<Contact[]> = this.contactsSubject.asObservable();

    constructor() {
        this.loadContacts();
    }

    private loadContacts(): void {
        try {
            const stored = localStorage.getItem(this.STORAGE_KEY);
            if (stored) {
                const parsed = JSON.parse(stored);
                if (Array.isArray(parsed)) {
                    this.contactsSubject.next(parsed);
                }
            }
        } catch (e) {
            console.error('Failed to load contacts from local storage:', e);
        }
    }

    private saveContacts(contacts: Contact[]): void {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(contacts));
            this.contactsSubject.next(contacts);
        } catch (e) {
            console.error('Failed to save contacts to local storage:', e);
        }
    }

    public getContacts(): Contact[] {
        return this.contactsSubject.value;
    }

    public getContactByAddress(address: string): Contact | undefined {
        if (!address) return undefined;
        const normalizedAddress = address.toLowerCase();
        return this.getContacts().find(c => c.address.toLowerCase() === normalizedAddress);
    }

    public addContact(contact: Contact): void {
        if (!contact || !contact.address) return;

        const contacts = this.getContacts();
        const existingIndex = contacts.findIndex(
            c => c.address.toLowerCase() === contact.address.toLowerCase()
        );

        if (existingIndex >= 0) {
            // Update existing
            contacts[existingIndex] = { ...contacts[existingIndex], ...contact };
        } else {
            // Add new
            contacts.push(contact);
        }

        this.saveContacts(contacts);
    }

    public removeContact(address: string): void {
        if (!address) return;

        const contacts = this.getContacts();
        const filtered = contacts.filter(
            c => c.address.toLowerCase() !== address.toLowerCase()
        );

        if (filtered.length !== contacts.length) {
            this.saveContacts(filtered);
        }
    }

    public updateContact(address: string, newLabel: string): void {
        if (!address) return;

        const contacts = this.getContacts();
        const contactIndex = contacts.findIndex(
            c => c.address.toLowerCase() === address.toLowerCase()
        );

        if (contactIndex >= 0) {
            contacts[contactIndex].label = newLabel;
            this.saveContacts(contacts);
        }
    }
}
