import { Component, EventEmitter, Input, Output, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { Contact } from '../../models/contact.model';
import { IconComponent } from '../../components/ui/icon/icon.component';
import { ToastService } from '../../services/toast.service';
import { AddressInputQrComponent } from '../../components/ui/address-input-qr/address-input-qr.component';

@Component({
    selector: 'app-contact-form-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, AddressInputQrComponent],
    templateUrl: './contact-form-modal.component.html',
    styleUrls: ['./contact-form-modal.component.scss']
})
export class ContactFormModalComponent implements OnInit, OnChanges {
    @Input() isOpen = false;
    @Input() contactToEdit: Contact | null = null;
    @Input() prefillAddress = '';

    @Output() closeModal = new EventEmitter<void>();
    @Output() saveContact = new EventEmitter<{ address: string, label: string }>();

    address = '';
    label = '';
    isEditMode = false;

    constructor(private toastService: ToastService) { }

    ngOnInit(): void { }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['contactToEdit']) {
            if (this.contactToEdit) {
                this.isEditMode = true;
                this.address = this.contactToEdit.address;
                this.label = this.contactToEdit.label || '';
            } else {
                this.isEditMode = false;
                this.address = this.prefillAddress || '';
                this.label = '';
            }
        }
        if (changes['isOpen'] && this.isOpen === true && !this.isEditMode) {
            this.address = this.prefillAddress || '';
            this.label = '';
        }
        if (changes['isOpen'] && this.isOpen === false) {
            // Reset state when closing normally
            this.address = '';
            this.label = '';
            this.isEditMode = false;
        }
    }

    close(): void {
        this.closeModal.emit();
    }

    save(): void {
        if (!this.address.trim()) {
            this.toastService.warning('Address cannot be empty');
            return;
        }
        if (!this.address.trim().startsWith('0x')) {
            this.toastService.warning('Address must start with 0x');
            return;
        }

        this.saveContact.emit({
            address: this.address.trim(),
            label: this.label.trim()
        });
        this.close();
    }
}
