import { Component, forwardRef, Input } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ToastService } from '@services/toast.service';
import { IconComponent } from '../icon/icon.component';
import { QrScannerComponent } from '../qr-scanner/qr-scanner.component';

@Component({
    selector: 'app-address-input-qr',
    standalone: true,
    imports: [CommonModule, FormsModule, IconComponent, QrScannerComponent],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => AddressInputQrComponent),
            multi: true
        }
    ],
    templateUrl: './address-input-qr.component.html',
    styleUrls: ['./address-input-qr.component.css']
})
export class AddressInputQrComponent implements ControlValueAccessor {
    @Input() placeholder = '0x...';
    @Input() label = '';
    @Input() disabled = false;

    address = '';
    showScanner = false;

    private onChange: (value: string) => void = () => { };
    private onTouched: () => void = () => { };

    constructor(private toastService: ToastService) { }

    onAddressChange(value: string) {
        this.address = value;
        this.onChange(value);
        this.onTouched();
    }

    writeValue(value: string): void {
        this.address = value || '';
    }

    registerOnChange(fn: (value: string) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    openScanner() {
        if (!this.disabled) {
            this.showScanner = true;
            this.onTouched();
        }
    }

    closeScanner() {
        this.showScanner = false;
    }

    handleScan(scannedAddress: string) {
        // Handle {"address": "0x..."} as per current QrScannerComponent format expectations in the app
        let addressToSet = scannedAddress;
        if (scannedAddress.includes('"address"')) {
            try {
                const parsed = JSON.parse(scannedAddress);
                if (parsed.address && typeof parsed.address === 'string') {
                    addressToSet = parsed.address;
                }
            } catch (e) { }
        } else if (scannedAddress.startsWith('ethereum:')) {
            addressToSet = scannedAddress.replace('ethereum:', '');
        }

        this.onAddressChange(addressToSet);
        this.closeScanner();
        this.toastService.success('CONTACTS.ADDRESS_SCANNED');
    }

    async copyAddress() {
        if (!this.address) return;
        try {
            await navigator.clipboard.writeText(this.address);
            this.toastService.success('CONTACTS.COPIED_SUCCESS');
        } catch (e) {
            this.toastService.error('Failed to copy address');
        }
    }
}
